import{j as e}from"./index-D8Ubnblb.js";import{L as n,S as t,a as s,C as i}from"./LegalLayout-Bc7Pxp2B.js";import{L as r}from"./react-vendor-AIXwcq2c.js";const o="altovisas@gmail.com",a="21 October 2026",l=[{id:"scope",title:"Who this covers"},{id:"collect",title:"What we collect"},{id:"never",title:"What we deliberately do not collect"},{id:"use",title:"How we use it"},{id:"bases",title:"Legal bases (EEA and UK)"},{id:"ai",title:"AI processing"},{id:"cookies",title:"Cookies, storage, and link tags"},{id:"sharing",title:"Who we share it with"},{id:"retention",title:"How long we keep it"},{id:"security",title:"Security"},{id:"rights",title:"Your rights"},{id:"delete",title:"Deleting your data"},{id:"transfers",title:"International transfers"},{id:"children",title:"Children"},{id:"changes",title:"Changes to this policy"},{id:"contact",title:"Contact"}];function u(){return e.jsxs(n,{title:"Privacy Policy",updated:a,toc:l,summary:e.jsxs(i,{children:[e.jsx("p",{className:"doc-callout-h",children:"The short version"}),e.jsxs("p",{children:["We collect what the Service needs to give you feedback, and not more. We do not sell your information, we do not run advertising, and we never share anything you write with any government or with your university. What you type stays private to your account; only anonymous, aggregated counts are used to see how the site is doing. Your profile and practice answers are scored by three AI providers, one of which processes data in China; section 6 explains what that means. You can delete your data at any time by emailing ",o,"."]})]}),children:[e.jsx(t,{id:"scope",title:"1. Who this covers",children:e.jsxs("p",{children:['This policy explains how Altovisas ("we", "us") handles personal information on altovisas.com (the "Service"). It applies whether or not you have an account. For the purposes of the UK and EU GDPR, Altovisas is the data controller. It should be read alongside our'," ",e.jsx(r,{to:"/terms",children:"Terms of Service"}),"."]})}),e.jsxs(t,{id:"collect",title:"2. What we collect",children:[e.jsx("p",{className:"doc-sub",children:"Information you give us"}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Account details."})," Your name and email address, and a hashed password. If you sign in with Google, we receive your name, email address, and profile picture from Google; we never see your Google password."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Your profile."})," What you tell us about your situation so the feedback can be about you: university and programme, degree level, academic record including GPA and test scores, intended consulate and country, funding, scholarship and sponsor information, work history, which visa attempt this is, and your plans after study."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Your practice answers."})," What you write in response to practice questions, and the reports we generate from them."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Purchases."})," If you buy a plan: which plan, the price, the date, and the payment reference our payment processor gives us. The processor collects your card or payment details directly; we never receive or store your full card number."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Refusal cover claims."})," If you claim the Complete plan’s refusal cover, the fact that you told us your visa was refused and the date you told us."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Feedback and surveys."})," Ratings, free-text comments, survey answers, and a waitlist email address if you give one."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Correspondence."})," Anything you send us by email."]})]}),e.jsx("p",{className:"doc-sub",children:"Information collected automatically"}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Usage events."})," Which pages you open, which steps of the flow you reach, roughly how long things take, whether you are on mobile or desktop, and your browser language. These are tied to a random identifier generated in your browser, not to your name."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Link tags."})," If you arrive on a link carrying a ",e.jsx("code",{children:"src"}),","," ",e.jsx("code",{children:"utm_source"}),", or ",e.jsx("code",{children:"ref"}),' value, we store that short label so we can see which channels bring people to the site. It is a channel name such as "reddit", never anything about you personally. See section 7.']}),e.jsxs("li",{children:[e.jsx("strong",{children:"Page analytics."})," We count page views with Umami Cloud, an analytics service that sets no cookies. It receives the page address, the site that sent you, your browser, operating system, device type, screen size, language, and approximate location (country or city), and nothing you type."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Technical information."})," Standard server logs, including IP address, user agent, and timestamps, kept for security and abuse prevention."]})]}),e.jsx("p",{children:'The usage event stream is built to be non-identifying. It deliberately strips out free text, names, email addresses, exact GPA figures, sponsor details, funding amounts, and your answers, and stores a banded value such as "3.0-3.3" instead of a precise one. Those private details live only in your account records, described above.'})]}),e.jsxs(t,{id:"never",title:"3. What we deliberately do not collect",children:[e.jsx("p",{children:"The Service never asks for, and does not want, any of the following. Please do not type them into any field:"}),e.jsxs(s,{children:[e.jsx("li",{children:"passport, visa, DS-160, or SEVIS numbers;"}),e.jsx("li",{children:"national identity numbers, including Social Security numbers;"}),e.jsx("li",{children:"bank account or card details (when you buy a plan, you enter these on our payment processor’s checkout, not into Altovisas);"}),e.jsx("li",{children:"photographs or scans of documents;"}),e.jsx("li",{children:"anyone else's personal information."})]}),e.jsxs("p",{children:["If you send us something like this anyway, tell us at ",o," and we will delete it. We also do not collect precise location, biometric data, or the special categories of data described in Article 9 of the GDPR, and we do not knowingly infer them."]})]}),e.jsxs(t,{id:"use",title:"4. How we use it",children:[e.jsxs(s,{children:[e.jsx("li",{children:"To create and secure your account, and to sign you in."}),e.jsx("li",{children:"To generate the feedback, statistics, and practice questions you asked for."}),e.jsx("li",{children:"To process purchases, give you the plan you paid for, handle refusal-cover claims and billing questions, and keep the records tax and accounting law requires."}),e.jsx("li",{children:"To send transactional email: verification codes, password resets, and important notices about the Service. We do not send marketing email unless you ask for it, and you can unsubscribe from anything that is not transactional."}),e.jsx("li",{children:"To understand how the Service is used in aggregate - where people get stuck, which steps take too long, which channels bring people here - so it can be improved."}),e.jsx("li",{children:"To detect, investigate, and prevent abuse, fraud, and security incidents."}),e.jsx("li",{children:"To comply with legal obligations and to establish or defend legal claims."})]}),e.jsx("p",{children:"We do not use your information for advertising, we do not build advertising profiles, and we do not make decisions with legal or similarly significant effects about you by automated means. The feedback the Service generates is informational only and decides nothing about you."})]}),e.jsxs(t,{id:"bases",title:"5. Legal bases (EEA and UK)",children:[e.jsx("p",{children:"If the UK or EU GDPR applies to you, we rely on:"}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Contract"})," - to provide the Service you asked for: your account, your feedback, your reports, and any plan you buy."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Legitimate interests"})," - to keep the Service secure, prevent abuse, and understand aggregate usage so we can improve it. We have weighed these against your rights, which is why the usage stream is stripped of personal detail."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Consent"})," - for anything optional, such as joining a waitlist. You can withdraw consent at any time."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Legal obligation"})," - where the law requires us to keep or disclose something, such as tax and accounting records of purchases."]})]})]}),e.jsxs(t,{id:"ai",title:"6. AI processing",children:[e.jsx("p",{children:"To generate your feedback, we send your profile and your practice answers to three third-party AI providers, which process them on our behalf and return a report. Every check goes to all three. You are shown one report; all three are stored with your account so we can compare the providers’ quality. We do not send your name, email address, or account identifiers to any of them, but anything you write inside an answer goes as written."}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Anthropic"})," (Claude), United States."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"OpenAI"})," (GPT), United States."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"DeepSeek"})," (DeepSeek’s API), which processes and stores data in the People’s Republic of China."]})]}),e.jsx("p",{children:"Anthropic’s and OpenAI’s commercial API terms do not allow them to use what we send to train their models, though they may keep it for a limited time to monitor abuse. DeepSeek’s own terms govern how it handles what it receives, and we cannot make the same commitment for it. We do not use your content to train any model of our own."}),e.jsx(i,{children:e.jsx("p",{children:"Because your answers are read by three outside providers in two countries, keep them to what the questions ask. Leave out names, contact details, and anything you would not want to leave your hands."})})]}),e.jsxs(t,{id:"cookies",title:"7. Cookies, storage, and link tags",children:[e.jsx("p",{children:"We use a small number of cookies and browser-storage entries, all functional:"}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Cookies."})," A secure, HTTP-only refresh-token cookie keeps you signed in for up to 30 days. An HTTP-only guest cookie identifies your browser before you sign in, so free usage is counted fairly. A short-lived cookie remembers which page to return you to during Google sign-in, and expires after five minutes."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Local storage."})," A random visitor identifier and a session identifier, used to group your own usage events together, and the link tag described below."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Session storage."})," Your sign-in token, and an unfinished profile check or survey, kept in that browser tab so a reload does not lose your work. All of it is cleared when the tab closes or you sign out."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"The link tag."})," When you arrive from a tagged link, we store its channel label so that later activity in the same browser is credited to the channel that introduced you. The first tag is kept, and it holds until you clear your browser storage."]})]}),e.jsx("p",{children:"We do not use third-party advertising cookies, cross-site trackers, or advertising pixels, and we do not sell or share personal information for cross-context behavioural advertising. Our usage events go to our own servers. Page-view counts go to Umami Cloud, which sets no cookies and does not track you across other sites."}),e.jsx("p",{children:"You can clear or block cookies and local storage in your browser settings. Blocking them will sign you out and reset the free-usage flow, but the rest of the Service will still work."})]}),e.jsxs(t,{id:"sharing",title:"8. Who we share it with",children:[e.jsxs("p",{children:[e.jsx("strong",{children:"We do not sell your personal information, and we never have."})," We share it only with service providers who process it on our behalf under contract, and only as far as they need to:"]}),e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Anthropic, OpenAI, and DeepSeek"})," - AI processing that generates your feedback (see section 6)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Google"})," - optional sign-in, if you use it."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Our payment processor"})," - taking payment when you buy a plan."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Umami"})," - cookie-free page-view counts."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Our email provider"})," - delivery of verification and account email."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Vercel and our database provider"})," - hosting the Service and storing its data."]})]}),e.jsxs("p",{children:["We may also disclose information if we are legally required to, to enforce our"," ",e.jsx(r,{to:"/terms",children:"Terms"}),", or to protect the rights and safety of our users or the public. If the Service is ever part of a merger, acquisition, or sale of assets, information may transfer to the new owner, who would remain bound by this policy or give you notice before changing it."]}),e.jsx(i,{children:e.jsx("p",{children:"We do not report anything you write to any immigration authority, embassy, consulate, university, or employer, and we do not receive anything about you from them. We have no relationship with any of them."})})]}),e.jsx(t,{id:"retention",title:"9. How long we keep it",children:e.jsxs(s,{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Account information"})," - while your account exists, then deleted within 30 days of your deletion request."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Profiles, answers, and reports"})," - while your account exists, so you can look back at them, then deleted with your account."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Usage events"})," - up to 24 months, in a form already stripped of personal detail, then deleted or aggregated permanently."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Purchase records"})," - for as long as tax and accounting law requires, even after your account is deleted."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Server logs"})," - up to 90 days."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Backups"})," - deleted records persist in encrypted backups until those backups rotate out, normally within 90 days."]})]})}),e.jsxs(t,{id:"security",title:"10. Security",children:[e.jsx("p",{children:"Traffic is encrypted in transit with HTTPS. Passwords are stored hashed, never in readable form. Data is held in access-controlled databases, and administrative access is limited to the people who need it. Sensitive fields are kept out of the analytics stream by design rather than by policy alone."}),e.jsx("p",{children:"No system is perfectly secure, and we cannot guarantee absolute security. If a breach affects your personal information, we will notify you and any relevant regulator as the law requires."})]}),e.jsxs(t,{id:"rights",title:"11. Your rights",children:[e.jsx("p",{children:"Depending on where you live, you may have the right to:"}),e.jsxs(s,{children:[e.jsx("li",{children:"access a copy of the personal information we hold about you;"}),e.jsx("li",{children:"correct information that is wrong or incomplete;"}),e.jsx("li",{children:"delete your information;"}),e.jsx("li",{children:"receive your information in a portable format;"}),e.jsx("li",{children:"object to or restrict certain processing;"}),e.jsx("li",{children:"withdraw consent you previously gave;"}),e.jsx("li",{children:"not be discriminated against for exercising any of these rights."})]}),e.jsxs("p",{children:["To exercise any of them, email"," ",e.jsx("a",{href:`mailto:${o}`,children:o})," ","from the address on your account. We respond within 30 days. We may need to verify who you are first, and an authorized agent may act for you with written permission."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"California residents."})," We do not sell or share personal information as those terms are used in the CCPA/CPRA, and we do not use or disclose sensitive personal information beyond the purposes permitted for providing the Service. The categories we collect, why, and who we disclose them to are set out in sections 2, 4, and 8."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"EEA and UK residents."})," You may also complain to your local supervisory authority, or in the UK to the Information Commissioner's Office. We would rather you came to us first."]})]}),e.jsxs(t,{id:"delete",title:"12. Deleting your data",children:[e.jsxs("p",{children:["Email ",o," from your account address and ask us to delete your account. We remove your account record, your profile, your practice answers, the reports generated for you, and your usage history, within 30 days, subject only to backup rotation and to anything we are legally required to keep, such as purchase records. Copies held by the AI providers under their own retention terms are not in our control, which is one more reason to keep answers to what the questions ask."]}),e.jsx("p",{children:"Aggregated statistics that can no longer identify you - counts, medians, approval shares - are not deleted, because they contain nothing that points back to you."})]}),e.jsxs(t,{id:"transfers",title:"13. International transfers",children:[e.jsx("p",{children:"We operate from and store data in the United States, and most of our service providers are U.S.-based. If you use the Service from outside the United States, your information will be transferred there, where data protection law differs from your own. Your profile and practice answers are also sent to DeepSeek in the People’s Republic of China to be scored (see section 6)."}),e.jsx("p",{children:"Where we transfer personal information out of the EEA or the UK, we rely on the safeguards our providers offer for such transfers, such as the European Commission’s Standard Contractual Clauses and the UK Addendum, where they offer them."})]}),e.jsx(t,{id:"children",title:"14. Children",children:e.jsxs("p",{children:["The Service is not directed to children under 16, and we do not knowingly collect their personal information. Users under 18 need the consent and involvement of a parent or guardian. If you believe a child under 16 has given us information, email"," ",o," and we will delete it promptly."]})}),e.jsx(t,{id:"changes",title:"15. Changes to this policy",children:e.jsx("p",{children:'We may update this policy. The "Last updated" date above always reflects the current version, and we will give notice on the Service, or by email to account holders, before a material change takes effect. Continuing to use the Service after that means you accept the updated policy.'})}),e.jsx(t,{id:"contact",title:"16. Contact",children:e.jsxs("p",{children:["Questions, requests, or complaints about privacy go to"," ",e.jsx("a",{href:`mailto:${o}`,children:o}),". We read everything sent there."]})})]})}export{u as default};
